theorem.raw:
\label{IVt:1}
Consider the setting of Problem~\ref{prob:1}. Let 
$h\in\Gamma_0(\ensuremath{{\mathcal X}})$ and $j\in\Gamma_0(\ensuremath{{\mathcal Y}})$ be Legendre 
functions such that $\ensuremath{\text{\rm int\,dom}\,} f\subset\ensuremath{\text{\rm int\,dom}\,} h$, 
$L(\ensuremath{\text{\rm int\,dom}\,} f)\subset\ensuremath{\text{\rm int\,dom}\,} j$, and there exist
$\varepsilon$ and $\delta$ in $\ensuremath{\left]0,+\infty\right[}$ such that 
$\nabla h+\varepsilon A$ and $\nabla j+\delta B$ are coercive. 
Let $\sigma\in\left[\max\{\varepsilon,\delta\},\ensuremath{{+\infty}}\right[$ 
and iterate
\begin{equation}
\label{IVe:Bfg+uh4f9-09h}
\begin{array}{l}
\text{for}\;n=0,1,\ldots\\
\left\lfloor
\begin{array}{l}
(\gamma_n,\mu_n)\in\left[\varepsilon,\sigma\right]
\times\left[\delta,\sigma\right]\\[1mm]
a_n=(\nabla h+\gamma_nA)^{-1}\big(\nabla h(x_n)-\gamma_n 
L^*y_n^*\big)\\[1mm]
a_n^*=\gamma_n^{-1}\big(\nabla h(x_n)-\nabla h(a_n)\big)-L^*y_n^*
\\[1mm]
b_n=(\nabla j+\mu_nB)^{-1}\big(\nabla j(Lx_n)+\mu_n y_n^*\big)
\\[1mm]
b_n^*=\mu_n^{-1}\big(\nabla j(Lx_n)-\nabla j(b_n)\big)+y_n^*
\\[1mm]
\boldsymbol{H}_n=
\menge{(x,y^*)\in\ensuremath{\boldsymbol{\mathcal X}}}{\pair{x}{a_n^*+L^*b_n^*}
+\pair{b_n-La_n}{y^*}\ensuremath{\leqslant}\pair{a_n}{a_n^*}+\pair{b_n}{b_n^*}}\\
(x_{n+1/2},y_{n+1/2}^*)=
P_{\boldsymbol{H}_n}^{\boldsymbol{f}}
(x_n,y_n^*)\\
(x_{n+1},y_{n+1}^*)=Q^{\boldsymbol{f}}
\big((x_0,y_0^*),(x_n,y_n^*),(x_{n+1/2},y_{n+1/2}^*)\big).
\end{array}
\right.\\
\end{array}
\end{equation}
Then the following hold:
\begin{enumerate}
\item
\label{IVt:1i} 
Let $n\in\ensuremath{\mathbb N}$. Then the following are equivalent:
\begin{enumerate}
\item
\label{IVt:1ia} 
$(x_n,y_n^*)=(\overline{x},\overline{y}^*)$.
\item
\label{IVt:1ib} 
$(x_n,y_n^*)\in\boldsymbol{Z}$.
\item
\label{IVt:1ic} 
$(x_n,y_n^*)\in\boldsymbol{H}_n$.
\item
\label{IVt:1id} 
$x_n=a_n$ and $y_n^*=b_n^*$.
\item
\label{IVt:1ie} 
$La_n=b_n$ and $a_n^*=-L^*b_n^*$.
\item
\label{IVt:1if} 
$\boldsymbol{H}_n=\ensuremath{\boldsymbol{\mathcal X}}$.
\item
\label{IVt:1ig} 
$(x_{n+1/2},y_{n+1/2}^*)=(x_n,y_n^*)$.
\item
\label{IVt:1ih} 
$(x_{n+1},y_{n+1}^*)=(x_n,y_n^*)$.
\end{enumerate}
\item
\label{IVt:1ii} 
$\sum_{n\in\ensuremath{\mathbb N}}D^f(x_{n+1},x_n)<\ensuremath{{+\infty}}$ and 
$\sum_{n\in\ensuremath{\mathbb N}}D^{g^*}(y_{n+1}^*,y_n^*)<\ensuremath{{+\infty}}$.
\item
\label{IVt:1iii} 
$\sum_{n\in\ensuremath{\mathbb N}}D^f(x_{n+1/2},x_n)<\ensuremath{{+\infty}}$ and 
$\sum_{n\in\ensuremath{\mathbb N}}D^{g^*}(y_{n+1/2}^*,y_n^*)<\ensuremath{{+\infty}}$.
\item
\label{IVt:1iv}
Suppose that $f$, $g^*$, $h$, and $j$ satisfy Condition~\ref{IVC:1},
and that $\nabla h$ and $\nabla j$ are uniformly continuous on 
every bounded subset of $\ensuremath{\text{\rm int\,dom}\,} h$ and $\ensuremath{\text{\rm int\,dom}\,} j$, respectively.
Then $x_n\to\overline{x}$ and $y_n^*\to\overline{y}^*$.
\end{enumerate}

lemma.raw:
\label{l:20}
Let $\ensuremath{{\mathcal X}}$ be a reflexive real Banach space such that 
$\ensuremath{{\mathcal X}}\neq\{0\}$ and let $M\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$.
Suppose that one of the following holds:
\begin{enumerate}
\item
\label{l:20i}
$\ensuremath{\text{\rm dom}\,} M$ is nonempty and bounded.
\item
\label{l:20ii}
$M$ is uniformly monotone at some point $z\in\ensuremath{\text{\rm dom}\,} M$ with a
supercoercive modulus: there exists a strictly increasing function 
$\phi\colon\left[0,+\infty\right[\to\left[0,+\infty\right]$ that 
vanishes only at $0$ such that 
$\lim\limits_{t\to+\infty}\phi(t)/t=+\infty$ and
\begin{equation}
(\forall (x,x^*)\in\ensuremath{\text{\rm gra}\,} M)(\forall z^*\in Mz)\quad 
\pair{x-z}{x^*-z^*}\ensuremath{\geqslant}\phi(\|x-z\|).
\end{equation}
\item
\label{l:20iii}
$M=\partial\varphi$, where $\varphi$ is a supercoercive function 
in $\Gamma_0(\ensuremath{{\mathcal X}})$.
\end{enumerate}
Then $M$ is coercive.

\label{IVlhHg7yG02}
Let $\ensuremath{{\mathcal X}}$ be a reflexive real Banach space such that 
$\ensuremath{{\mathcal X}}\neq\{0\}$, let $M_1\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$, and let 
$M_2\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$ be monotone. Suppose that there 
exists $z\in\ensuremath{\text{\rm dom}\,} M_1\cap\ensuremath{\text{\rm dom}\,} M_2$ such that
\begin{equation}
\label{e:M1}
\lim\limits_{\|x\|\to+\infty}\inf\dfrac{\pair{x-z}{M_1x}}{\|x\|}
=\ensuremath{{+\infty}}.
\end{equation} 
Then $M_1+M_2$ is coercive.

\label{IVlKKnhf74g12}
Let $\ensuremath{{\mathcal X}}$ be a reflexive real Banach space such that 
$\ensuremath{{\mathcal X}}\neq\{0\}$, let $M_1\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$, let 
$M_2\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$ be monotone, let $(x_n^*)_{n\in\ensuremath{\mathbb N}}$ 
be a bounded sequence in $\ensuremath{{\mathcal X}}^*$, and let $(\gamma_n)_{n\in\ensuremath{\mathbb N}}$ 
be a bounded sequence in $\ensuremath{\left]0,+\infty\right[}$. Suppose that there exists 
$z\in\ensuremath{\text{\rm dom}\,} M_1\cap\ensuremath{\text{\rm dom}\,} M_2$ such that
\begin{equation}
\label{eKKnhf74g13b}
\lim_{\|x\|\to+\infty}\inf\dfrac{\pair{x-z}{M_1x}}{\|x\|}=\ensuremath{{+\infty}},
\end{equation} 
and that
\begin{equation}
\label{eKKnhf74g12a}
(\forall n\in\ensuremath{\mathbb N})\quad x_n\in(M_1+\gamma_n M_2)^{-1}x_n^*.
\end{equation}
Then $(x_n)_{n\in\ensuremath{\mathbb N}}$ is bounded.

\label{IVlKKnhf74g10}
Let $\ensuremath{{\mathcal X}}$ and $\ensuremath{{\mathcal Y}}$ be real Banach spaces, let $D\subset\ensuremath{{\mathcal X}}$
be a nonempty open set, and let $C$ be a nonempty bounded convex 
subset of $D$. Suppose that $T\colon D\to\ensuremath{{\mathcal Y}}$ is uniformly 
continuous on $C$ in the sense that 
\begin{equation}
\label{eKKnhf74g15t}
(\forall\varepsilon\in\ensuremath{\left]0,+\infty\right[})(\ensuremath{\exists\,}\delta\in\ensuremath{\left]0,+\infty\right[})(\forall x\in C)
(\forall y\in C)\quad
\|x-y\|\ensuremath{\leqslant}\delta\;\Rightarrow\;
\|Tx-Ty\|\ensuremath{\leqslant}\varepsilon.
\end{equation}
Then $T$ is bounded on $C$.

proposition.raw:
\label{ppOlk28ha12}
Consider the setting of Problem~\ref{prob:1}. Then the 
following hold:
\begin{enumerate}
\item
\label{ppOlk28ha12i}
Let $\mathscr{P}$ be the set of solutions to \eqref{Ipb:Ia} and 
let $\mathscr{D}$ be the set of solutions to \eqref{Ipb:Ib}. Then 
the following hold:
\begin{enumerate}
\item
\label{ppOlk28ha12ia}
$\boldsymbol{Z}$ is a closed convex subset of 
$\mathscr{P}\times\mathscr{D}$.
\item
\label{ppOlk28ha12ib}
Set $\mathcal{Q}_\ensuremath{{\mathcal X}}\colon\ensuremath{\boldsymbol{\mathcal X}}\to\ensuremath{{\mathcal X}}\colon (x,y^*)\mapsto x$
and $\mathcal{Q}_{\ensuremath{{\mathcal Y}}^*}\colon\ensuremath{\boldsymbol{\mathcal X}}\to\ensuremath{{\mathcal Y}}^*\colon (x,y^*)\mapsto y^*$.
Then $\mathscr{P}=\mathcal{Q}_\ensuremath{{\mathcal X}}(\boldsymbol{Z})$ and 
$\mathscr{D}=\mathcal{Q}_{\ensuremath{{\mathcal Y}}^*}(\boldsymbol{Z})$. 
\item
\label{ppOlk28ha12ic}
$\mathscr{P}\neq\ensuremath{{\varnothing}}\Leftrightarrow\boldsymbol{Z}
\neq\ensuremath{{\varnothing}}\Leftrightarrow\mathscr{D}\neq\ensuremath{{\varnothing}}$.
\end{enumerate}
\item
\label{ppOlk28ha12ii}
For every $\mathsf{a}=(a,a^*)\in\ensuremath{\text{\rm gra}\,} A$ and 
$\mathsf{b}=(b,b^*)\in\ensuremath{\text{\rm gra}\,} B$, set
$\boldsymbol{s}_{\mathsf{a},\mathsf{b}}^*=(a^*+L^*b^*,b-La)$, 
$\eta_{\mathsf{a},\mathsf{b}}=\pair{a}{a^*}+\pair{b}{b^*}$, and 
$\boldsymbol{H}_{\mathsf{a},\mathsf{b}}=
\menge{\boldsymbol{x}\in\boldsymbol{\mathcal{X}}}
{\pair{\boldsymbol{x}}{\boldsymbol{s}_{\mathsf{a},\mathsf{b}}^*}
\ensuremath{\leqslant}\eta_{\mathsf{a},\mathsf{b}}}$. Then the following hold:
\begin{enumerate}
\item
\label{ppOlk28ha12iia}
$(\forall\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A)(\forall\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B)$ 
$[\,\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}
=\boldsymbol{0}\;\Leftrightarrow\;
\boldsymbol{H}_{\mathsf{a},\mathsf{b}}
=\ensuremath{\boldsymbol{\mathcal X}}\;\Rightarrow\;(a,b^*)\in\boldsymbol{Z}
\;\text{and}\;\eta_{\mathsf{a},\mathsf{b}}=0\,]$.
\item
\label{ppOlk28ha12iib}
$\boldsymbol{Z}=\bigcap_{\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A}
\bigcap_{\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B}
\boldsymbol{H}_{\mathsf{a},\mathsf{b}}$\,.
\end{enumerate}
\item
\label{ppOlk28ha12iii}
Let $(a_n,a_n^*)_{n\in\ensuremath{\mathbb N}}$ be a sequence 
in $\ensuremath{\text{\rm gra}\,} A$, let $(b_n,b_n^*)_{n\in\ensuremath{\mathbb N}}$ be a sequence in 
$\ensuremath{\text{\rm gra}\,} B$, and let $(x,y^*)\in\ensuremath{\boldsymbol{\mathcal X}}$. 
Suppose that $a_n\ensuremath{\:\rightharpoonup\:} x$, $b_n^*\ensuremath{\:\rightharpoonup\:} y^*$, 
$a_n^*+L^*b_n^*\to 0$, and $La_n-b_n\to 0$. Then 
$(x,y^*)\in\boldsymbol{Z}$.
\end{enumerate}

\label{pvb8uh4504}
Consider the setting of Problem~\ref{prob:1}. Then the 
following hold:
\begin{enumerate}
\item
\label{pvb8uh4504i}
$\boldsymbol{f}$ is a Legendre function.
\item
\label{pvb8uh4504ii}
The solution $(\overline{x},\overline{y}^*)$ to
Problem~\ref{prob:1} exists and is unique.
\end{enumerate}

\label{p:2}
Let $\ensuremath{\boldsymbol{\mathcal X}}$ be a reflexive real Banach space, let 
$\boldsymbol{f}\in\Gamma_0(\ensuremath{\boldsymbol{\mathcal X}})$ be a Legendre 
function, let $\boldsymbol{C}$ be a closed convex subset 
of $\overline{\ensuremath{\text{\rm dom}\,}}\boldsymbol{f}$ such that 
$\boldsymbol{C}\cap\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}\neq\ensuremath{{\varnothing}}$,
let $\boldsymbol{x}_0\in\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}$, and set 
$\overline{\boldsymbol{x}}=P_{\boldsymbol{C}}^{\boldsymbol{f}}
\boldsymbol{x}_0$. 
At every iteration $n\in\ensuremath{\mathbb N}$, find 
$\boldsymbol{x}_{n+1/2}\in\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,}\boldsymbol{f}$ such that 
$\boldsymbol{C}\subset H^{\boldsymbol{f}}
(\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2})$ and set
\begin{equation}
\label{e:haugazeau}
\boldsymbol{x}_{n+1}=Q^{\boldsymbol{f}}
\big(\boldsymbol{x}_0,\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2}\big).
\end{equation}
Then the following hold:
\begin{enumerate}
\item
\label{p:2i-}
$(\forall n\in\ensuremath{\mathbb N})$ $\boldsymbol{C}\subset H^{\boldsymbol{f}}
(\boldsymbol{x}_0,\boldsymbol{x}_n)$.
\item
\label{p:2i}
$(\boldsymbol{x}_n)_{n\in\ensuremath{\mathbb N}}$ is a well-defined bounded sequence 
in $\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}$.
\item
\label{p:2ii+} 
Suppose that, for some $n\in\ensuremath{\mathbb N}$, 
$\boldsymbol{x}_n\in\boldsymbol{C}$. Then $(\forall k\in\ensuremath{\mathbb N})$ 
$\boldsymbol{x}_{n+k}=\overline{\boldsymbol{x}}$.
\item
\label{p:2ii} 
$\sum_{n\in\ensuremath{\mathbb N}}D^{\boldsymbol{f}}(\boldsymbol{x}_{n+1},
\boldsymbol{x}_n)<+\infty$.
\item
\label{p:2iii-} 
$(\forall n\in\ensuremath{\mathbb N})$ $D^{\boldsymbol{f}}
(\boldsymbol{x}_{n+1/2},\boldsymbol{x}_n)\ensuremath{\leqslant} 
D^{\boldsymbol{f}}(\boldsymbol{x}_{n+1},\boldsymbol{x}_n)$.
\item
\label{p:2iii} 
$\sum_{n\in\ensuremath{\mathbb N}}D^{\boldsymbol{f}}(\boldsymbol{x}_{n+1/2},
\boldsymbol{x}_n)<+\infty$.
\item
\label{p:2iv} 
$[\,\boldsymbol{x}_n\ensuremath{\:\rightharpoonup\:}\overline{\boldsymbol{x}}$ and 
$\boldsymbol{f}(\boldsymbol{x}_n)\to\boldsymbol{f}
(\overline{\boldsymbol{x}})\,]$ 
$\Leftrightarrow$ $D^{\boldsymbol{f}}(\boldsymbol{x}_n,
\overline{\boldsymbol{x}})\to 0$ 
$\Leftrightarrow$
$\ensuremath{{\mathfrak W}}(\boldsymbol{x}_n)_{n\in\ensuremath{\mathbb N}}\subset\boldsymbol{C}$. 
\end{enumerate}

\label{IVpp:20a}
Let $\ensuremath{{\mathcal X}}$ be a reflexive real Banach space such that 
$\ensuremath{{\mathcal X}}\neq\{0\}$, let $h\in\Gamma_0(\ensuremath{{\mathcal X}})$ be essentially smooth, 
and let $M\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$ be such that 
$\ensuremath{\text{\rm dom}\,} M\cap\ensuremath{\text{\rm int\,dom}\,} h\neq\ensuremath{{\varnothing}}$. Suppose that 
one of the following holds:
\begin{enumerate}
\item
\label{IVcl:20b1}
$\ensuremath{\text{\rm dom}\,} M\cap\ensuremath{\text{\rm int\,dom}\,} h$ is bounded.
\item
\label{IVcl:20b2}
There exists $z\in\ensuremath{\text{\rm dom}\,} M\cap\ensuremath{\text{\rm int\,dom}\,} h$ such that
\begin{equation}
\lim_{\|x\|\to+\infty}\inf\dfrac{\pair{x-z}{Mx}}{\|x\|}
=\ensuremath{{+\infty}}.
\end{equation} 
\item
\label{IVcl:20b3}
$M$ is uniformly monotone at a point 
$z\in\ensuremath{\text{\rm dom}\,} M\cap\ensuremath{\text{\rm int\,dom}\,} h$ with a
supercoercive modulus.
\item
\label{IVcl:20b4}
$M$ is monotone and $h$ is supercoercive.
\item
\label{IVcl:20b5}
$M$ is monotone and $h$ is uniformly convex at a point 
$z\in\ensuremath{\text{\rm dom}\,} M\cap\ensuremath{\text{\rm int\,dom}\,} h$, i.e., there exists an increasing 
function 
$\phi\colon\left[0,+\infty\right[\to\left[0,+\infty\right]$ 
that vanishes only at $0$ such that 
\begin{equation}
(\forall y\in\ensuremath{\text{\rm dom}\,} h)(\forall\alpha\in\left]0,1\right[)\;\;
h(\alpha y+(1-\alpha)z)+\alpha(1-\alpha)\phi(\|y-z\|)
\ensuremath{\leqslant}\alpha h(y)+(1-\alpha)h(z).
\end{equation}
\end{enumerate}
Then $\nabla h+M$ is coercive. If, in addition, $M$ is 
maximally monotone, then $\ensuremath{\text{\rm dom}\,}(\nabla h+M)^{-1}=\ensuremath{{\mathcal X}}^*$.

problem.raw:
\label{prob:1}
Let $\ensuremath{{\mathcal X}}$ and $\ensuremath{{\mathcal Y}}$ be reflexive real Banach spaces such that
$\ensuremath{{\mathcal X}}\neq\{0\}$ and $\ensuremath{{\mathcal Y}}\neq\{0\}$, let $\ensuremath{\boldsymbol{\mathcal X}}$ be the standard 
product vector space $\ensuremath{{\mathcal X}}\times\ensuremath{{\mathcal Y}}^*$ equipped with the norm 
$(x,y^*)\mapsto\sqrt{\|x\|^2+\|y^*\|^2}$, and let $\ensuremath{\boldsymbol{\mathcal X}}^*$ be its 
topological dual, that is, $\ensuremath{{\mathcal X}}^*\times\ensuremath{{\mathcal Y}}$ equipped with 
the norm $(x^*,y)\mapsto\sqrt{\|x^*\|^2+\|y\|^2}$.
Let $A\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$ and 
$B\colon\ensuremath{{\mathcal Y}}\to 2^{\ensuremath{{\mathcal Y}}^*}$ be maximally monotone, and
let $L\colon\ensuremath{{\mathcal X}}\to\ensuremath{{\mathcal Y}}$ be linear and bounded. Consider the
inclusion problem
\begin{equation}
\label{Ipb:Ia}
\text{find}\;\;x\in\ensuremath{{\mathcal X}}\;\;\text{such that}\;\;0\in Ax+L^*BLx,
\end{equation}
the dual problem
\begin{equation}
\label{Ipb:Ib}
\text{find}\;\;y^*\in\ensuremath{{\mathcal Y}}^*\;\;\text{such that}\;\; 
0\in -LA^{-1}(-L^*y^*)+B^{-1}y^*,
\end{equation}
and let 
\begin{equation}
\label{IVe:VKT}
\boldsymbol{Z}
=\menge{(x,y^*)\in\boldsymbol{\mathcal{X}}}{-L^*y^*\in Ax
\quad\text{and}\quad Lx\in B^{-1}y^*}
\end{equation}
be the associated Kuhn-Tucker set.
Let $f\colon\ensuremath{{\mathcal X}}\to\ensuremath{\left]-\infty,+\infty\right]}$ and $g\colon\ensuremath{{\mathcal Y}}\to\ensuremath{\left]-\infty,+\infty\right]}$ be Legendre 
functions, set
\begin{equation}
\label{epOlk28ha14}
\boldsymbol{f}\colon\ensuremath{\boldsymbol{\mathcal X}}\to\ensuremath{\left]-\infty,+\infty\right]}\colon(x,y^*)\mapsto f(x)+g^*(y^*),
\end{equation}
let $x_0\in\ensuremath{\text{\rm int\,dom}\,} f$, let $y_0^*\in\ensuremath{\text{\rm int\,dom}\,} g^*$, 
and suppose that 
$\boldsymbol{Z}\cap\text{\rm int\,dom}\,\boldsymbol{f}\neq\ensuremath{{\varnothing}}$.
The problem is to find the best Bregman approximation 
$(\overline{x},\overline{y}^*)=P^{\boldsymbol{f}}_{\boldsymbol{Z}}
(x_0,y_0^*)$ to $(x_0,y_0^*)$ from $\boldsymbol{Z}$.

proof.raw:
Item~\ref{p:2i-} is found in 
\cite[Proof of Proposition~3.3]{Pams03}.
The first equivalence in \ref{p:2iv} follows from
\cite[Propositions~2.2(ii)]{Pams03}. To establish the remaining
assertions, set
\begin{equation}
\label{epOlk28ha21a}
(\forall n\in\ensuremath{\mathbb N})\quad T_n=
P_{H^{\boldsymbol{f}}
(\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2})}^{\boldsymbol{f}}.
\end{equation}
Then, for every $n\in\ensuremath{\mathbb N}$, Definition~\ref{d:B-haugazeau}
yields
$T_n\boldsymbol{x}_n=\boldsymbol{x}_{n+1/2}$, 
\cite[Proposition~3.32(ii)(b)]{Sico03} yields
$\ensuremath{\text{\rm Fix}\,} T_n=H^{\boldsymbol{f}}(\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2})
\cap\ensuremath{\text{\rm int\:dom}\boldsymbol{f}}$, and we derive from Lemma~\ref{l:2002} that
\begin{equation}
\label{epOlk28ha21b}
\boldsymbol{C}\subset H^{\boldsymbol{f}}
(\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2})
\cap\overline{\ensuremath{\text{\rm dom}\,}}\boldsymbol{f}=
\overline{H^{\boldsymbol{f}}
(\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2})\cap\ensuremath{\text{\rm int\:dom}\boldsymbol{f}}}
=\overline{\ensuremath{\text{\rm Fix}\,}}T_n.
\end{equation}
On the other hand,
\begin{equation}
\label{epOlk28ha21c1}
(\forall n\in\ensuremath{\mathbb N})\quad\ensuremath{{\varnothing}}\neq \boldsymbol{C}\cap\ensuremath{\text{\rm int\,dom}\,}
\boldsymbol{f}\subset
H^{\boldsymbol{f}}(\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2})
\cap\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}=\ensuremath{\text{\rm Fix}\,} T_n
\end{equation}
and, therefore, $\bigcap_{n\in\ensuremath{\mathbb N}}\ensuremath{\text{\rm Fix}\,} T_n\neq\ensuremath{{\varnothing}}$.
Altogether, \cite[Condition~3.2]{Pams03} is satisfied
and it follows from \cite[Propositions~3.3 and 3.4]{Pams03} 
and \cite[Proof of Proposition~3.4(vii)]{Pams03} 
that the proof is complete.

\ref{l:20i}:
Let $x\in\ensuremath{{\mathcal X}}$ and let $z\in\ensuremath{\text{\rm dom}\,} M$. Then, if $\|x\|$ is
sufficiently large, we have $Mx=\ensuremath{{\varnothing}}$ and therefore 
$\inf{\pair{x-z}{Mx}}/{\|x\|}=\ensuremath{{+\infty}}$.

\ref{l:20ii}: We have
\begin{equation}
(\forall (x,x^*)\in\ensuremath{\text{\rm gra}\,} M)(\forall z^*\in Mz)\quad 
\pair{x-z}{x^*-z^*}\ensuremath{\geqslant}\phi(\|x-z\|).
\end{equation}
Hence, for every $x\in\ensuremath{\text{\rm dom}\,} M$ such that $\|x\|>\|z\|$, we have
\begin{align}
(\forall x^*\in Mx)(\forall z^*\in Mz)\quad
\dfrac{\pair{x-z}{x^*}}{\|x\|}
&\ensuremath{\geqslant}\dfrac{\phi(\|x-z\|)-\|x-z\|\,\|z^*\|}{\|x\|}\nonumber\\
&=\dfrac{\|x-z\|}{\|x\|}\bigg(
\dfrac{\phi(\|x-z\|)}{\|x-z\|}-\|z^*\|\bigg).
\end{align}
Thus, 
\begin{equation}
\lim_{\|x\|\to+\infty}\inf\dfrac{\pair{x-z}{Mx}}{\|x\|}=\ensuremath{{+\infty}}.
\end{equation}

\ref{l:20iii}: In view of \ref{l:20i}, we suppose that
$\ensuremath{\text{\rm dom}\,} M$ is unbounded. Let $z\in\ensuremath{\text{\rm dom}\,} M$. Then we derive from 
\eqref{e:subdiff} that, for every 
$x\in\ensuremath{\text{\rm dom}\,} M\smallsetminus\{0\}$,
\begin{equation}
\label{eQA8h34-05}
(\forall x^*\in Mx)\quad\dfrac{\varphi(x)-\varphi(z)}{\|x\|}\ensuremath{\leqslant}
\dfrac{\pair{x-z}{x^*}}{\|x\|}.
\end{equation}
Hence, the supercoercivity of $\varphi$ yields
\begin{equation}
\label{eQA8h34-06}
\lim_{\|x\|\to+\infty}\inf\dfrac{\pair{x-z}{Mx}}{\|x\|}=\ensuremath{{+\infty}}
\end{equation}
and $M$ is therefore coercive.

Suppose that $x\in(\ensuremath{\text{\rm dom}\,} M_1\cap\ensuremath{\text{\rm dom}\,} M_2)\smallsetminus\{0\}$, let 
$x^*\in(M_1+M_2)x$, and let $z^*\in(M_1+M_2)z$. 
Then there exist $x_1^*\in M_1x$, 
$x_2^*\in M_2x$, $z_1^*\in M_1z$, and $z_2^*\in M_2z$ such that
$x^*=x_1^*+x_2^*$ and $z^*=z_1^*+z_2^*$. In turn, the monotonicity
of $M_2$ yields
\begin{align}
\dfrac{\pair{x-z}{x^*}}{\|x\|}
&=\dfrac{\pair{x-z}{x_1^*-z_1^*}}{\|x\|}
+\dfrac{\pair{x-z}{x_2^*-z_2^*}}{\|x\|}
+\dfrac{\pair{x-z}{z^*}}{\|x\|}\nonumber\\
&\ensuremath{\geqslant}\dfrac{\pair{x-z}{x_1^*}}{\|x\|}
+\dfrac{\pair{x-z}{z_2^*}}{\|x\|}\nonumber\\
&\ensuremath{\geqslant}\dfrac{\pair{x-z}{x_1^*}-\|x-z\|\,\|z_2^*\|}{\|x\|}
\end{align}
and \eqref{e:M1} implies that $M_1+M_2$ is coercive.

Set $\beta=\sup_{n\in\ensuremath{\mathbb N}}\|x_n^*\|$ and 
$\sigma=\sup_{n\in\ensuremath{\mathbb N}}\gamma_n$. It follows from
\eqref{eKKnhf74g12a} that, for every $n\in\ensuremath{\mathbb N}$, there exist
$a_n^*\in M_1x_n$ and $b_n^*\in M_2x_n$ such that
$x_n^*=a_n^*+\gamma_n b_n^*$. If $(x_n)_{n\in\ensuremath{\mathbb N}}$ is  
unbounded, there exists a strictly increasing sequence 
$(k_n)_{n\in\ensuremath{\mathbb N}}$ in $\ensuremath{\mathbb N}$ such that $0<\|x_{k_n}\|\uparrow\ensuremath{{+\infty}}$.
Therefore, \eqref{eKKnhf74g13b} yields
\begin{equation}
\label{eKKnhf74g13a}
\lim_{n\to\ensuremath{{+\infty}}}
\dfrac{\pair{x_{k_n}-z}{a^*_{k_n}}}{\|x_{k_n}\|}=\ensuremath{{+\infty}}.
\end{equation} 
Now let $z^*\in M_2 z$. By monotonicity of $M_2$,
$(\forall n\in\ensuremath{\mathbb N})$ $\pair{x_{k_n}-z}{b_{k_n}^*-z^*}\ensuremath{\geqslant} 0$.
Hence, \eqref{eKKnhf74g13a} implies that
\begin{align}
\label{eKKnhf74g12b}
\beta\bigg(1+\dfrac{\|z\|}{\|x_{k_0}\|}\bigg)
&\ensuremath{\geqslant}\beta\bigg(1+\dfrac{\|z\|}{\|x_{k_n}\|}\bigg)\nonumber\\
&\ensuremath{\geqslant}\beta\dfrac{\|x_{k_n}-z\|}{\|x_{k_n}\|}\nonumber\\
&\ensuremath{\geqslant}\dfrac{\pair{x_{k_n}-z}{x_{k_n}^*}}{\|x_{k_n}\|}\nonumber\\
&=\dfrac{\pair{x_{k_n}-z}{a_{k_n}^*}}{\|x_{k_n}\|}
+\gamma_{k_n}\dfrac{\pair{x_{k_n}-z}{b_{k_n}^*-z^*}}{\|x_{k_n}\|}
+\gamma_{k_n}\dfrac{\pair{x_{k_n}-z}{z^*}}{\|x_{k_n}\|}\nonumber\\
&\ensuremath{\geqslant}\dfrac{\pair{x_{k_n}-z}{a_{k_n}^*}}{\|x_{k_n}\|}
-\sigma\dfrac{\|x_{k_n}-z\|\,\|z^*\|}{\|x_{k_n}\|}\nonumber\\
&\ensuremath{\geqslant}\dfrac{\pair{x_{k_n}-z}{a_{k_n}^*}}{\|x_{k_n}\|}
-\sigma\|z^*\|\bigg(1+\dfrac{\|z\|}{\|x_{k_0}\|}\bigg)\nonumber\\
&\to\ensuremath{{+\infty}},
\end{align}
and we reach a contradiction.

We apply Proposition~\ref{p:2} to 
\begin{equation}
\label{4e:C}
\boldsymbol{C}=\boldsymbol{Z}\cap\overline{\ensuremath{\text{\rm dom}\,}}\boldsymbol{f}.
\end{equation}
It follows from Proposition~\ref{ppOlk28ha12}\ref{ppOlk28ha12ia}
and our assumptions that $\boldsymbol{C}$ is a closed convex 
subset of $\overline{\ensuremath{\text{\rm dom}\,}}\boldsymbol{f}$ and that
$\boldsymbol{C}\cap\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}\neq\ensuremath{{\varnothing}}$. 
Moreover, Proposition~\ref{pvb8uh4504}\ref{pvb8uh4504i}
asserts that $\boldsymbol{f}$ is a Legendre function.
Now let $\gamma\in[\varepsilon,\ensuremath{{+\infty}}[$ and let 
$\mu\in[\delta,\ensuremath{{+\infty}}[$.
Since $h$ is strictly convex, $\nabla h$ is 
strictly monotone \cite[Theorem~2.4.4(ii)]{IVZali02} and 
$\nabla h+\gamma A$ is likewise. Let $(x^*,x_1)$ and 
$(x^*,x_2)$ be two elements in $\ensuremath{\text{\rm gra}\,}(\nabla h+\gamma A)^{-1}$ 
such that $x_1\not=x_2$. Then $(x_1,x^*)$ and $(x_2,x^*)$ lie in 
$\ensuremath{\text{\rm gra}\,}(\nabla h+\gamma A)$ and the strict monotonicity of 
$\nabla h+\gamma A$ implies that 
\begin{equation}
0=\pair{x_1-x_2}{x^*-x^*}>0,
\end{equation}
which is impossible. Thus,
\begin{equation}
\label{4e:single1}
(\nabla h+\gamma A)^{-1}\;\text{is at most single-valued}.
\end{equation} 
The same argument shows that
\begin{equation}
\label{4e:single2}
(\nabla j+\mu B)^{-1}\;\text{is at most single-valued}.
\end{equation} 
On the other hand, by assumption, there exists
$(x,y^*)\in\boldsymbol{Z}\cap\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}$.
It follows from \eqref{IVe:VKT} that $x\in\ensuremath{\text{\rm dom}\,} A$ and 
$Lx\in\ensuremath{\text{\rm dom}\,} B$. Furthermore, \eqref{ebcn5y731} yields 
$x\in\ensuremath{\text{\rm int\,dom}\,} f$. Therefore
\begin{equation}
\label{ehHg7yG10a}
\begin{cases}
x\in\ensuremath{\text{\rm dom}\,} A\cap\ensuremath{\text{\rm int\,dom}\,} f\subset\ensuremath{\text{\rm dom}\,} A\cap\ensuremath{\text{\rm int\,dom}\,} h\\
Lx\in\ensuremath{\text{\rm dom}\,} B\cap L(\ensuremath{\text{\rm int\,dom}\,} f)\subset\ensuremath{\text{\rm dom}\,} B\cap\ensuremath{\text{\rm int\,dom}\,} j.
\end{cases}
\end{equation}
Thus, $\ensuremath{\text{\rm dom}\,} A\cap\ensuremath{\text{\rm int\,dom}\,} h\neq\ensuremath{{\varnothing}}$ and
$\ensuremath{\text{\rm dom}\,} B\cap\ensuremath{\text{\rm int\,dom}\,} j\neq\ensuremath{{\varnothing}}$. It therefore follows from
Lemma~\ref{IVlhHg7yG02} that
\begin{equation}
\label{4e:single3}
\nabla h+\gamma A=(\nabla h+\varepsilon A)+(\gamma-\varepsilon)A 
\quad\text{and}\quad
\nabla j+\mu B=(\nabla j+\delta B)+(\mu-\delta)B
\;\;\text{are coercive}.
\end{equation}
Altogether, \eqref{4e:single1}, \eqref{4e:single2}, 
\eqref{4e:single3}, and Proposition~\ref{IVpp:20a} assert 
that the operators
\begin{equation}
\label{4:e12}
\begin{cases}
(\nabla h+\gamma A)^{-1}\colon\ensuremath{{\mathcal X}}^*\to\ensuremath{\text{\rm dom}\,} A\cap\ensuremath{\text{\rm int\,dom}\,} h\\
(\nabla j+\mu B)^{-1}\colon\ensuremath{{\mathcal Y}}^*\to\ensuremath{\text{\rm dom}\,} B\cap\ensuremath{\text{\rm int\,dom}\,} j
\end{cases}
\end{equation}
are well defined and single-valued. Now set
\begin{equation}
\label{eKKnhf74g05}
(\forall n\in\ensuremath{\mathbb N})\quad
\boldsymbol{x}_n=(x_n,y_n^*)\quad\text{and}\quad
\boldsymbol{x}_{n+1/2}=(x_{n+1/2},y_{n+1/2}^*).
\end{equation}
Since \eqref{IVe:Bfg+uh4f9-09h} yields
\begin{equation}
\label{eKKnhf74g04}
(\forall n\in\ensuremath{\mathbb N})\quad
(a_n,a_n^*)\in\ensuremath{\text{\rm gra}\,} A\quad\text{and}\quad (b_n,b_n^*)\in\ensuremath{\text{\rm gra}\,} B,
\end{equation}
it follows from \eqref{4e:C}, 
Proposition~\ref{ppOlk28ha12}\ref{ppOlk28ha12iib},
\eqref{IVe:Bfg+uh4f9-09h}, and 
Definition~\ref{d:B-haugazeau} that
\begin{equation}
\label{eKKnhf74g03}
(\forall n\in\ensuremath{\mathbb N})\quad
\ensuremath{{\varnothing}}\neq\boldsymbol{C}\subset\boldsymbol{Z}\subset\boldsymbol{H}_n
=H^{\boldsymbol{f}}(\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2}).
\end{equation}
Hence, appealing to 
Proposition~\ref{pvb8uh4504}\ref{pvb8uh4504i} and 
\eqref{e:2001}, we see that
\begin{equation}
\label{IVe:32a}
(\forall n\in\ensuremath{\mathbb N})\quad
P_{\boldsymbol{H}_n}^{\boldsymbol{f}}
\colon\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}\to
\boldsymbol{H}_n\cap\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}
\end{equation}
and that
\begin{equation}
\label{eKKnhf74g04i}
(\forall n\in\ensuremath{\mathbb N})\quad
\boldsymbol{x}_{n+1}=Q^{\boldsymbol{f}}
\big(\boldsymbol{x}_0,\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2}\big).
\end{equation}
Thus, we derive from 
\eqref{eKKnhf74g05}, \eqref{eKKnhf74g03}, and 
Proposition~\ref{p:2}\ref{p:2i} that
$(x_n)_{n\in\ensuremath{\mathbb N}}$ and $(y_n^*)_{n\in\ensuremath{\mathbb N}}$ are well-defined
sequences in $\ensuremath{\text{\rm int\,dom}\,} f$ and $\ensuremath{\text{\rm int\,dom}\,} g^*$, respectively.

\ref{IVt:1i}: We prove the following implications.

\ref{IVt:1ia}$\Rightarrow$\ref{IVt:1ib}: Clear.

\ref{IVt:1ib}$\Rightarrow$\ref{IVt:1ia}: 
Proposition~\ref{p:2}\ref{p:2ii+}.

\ref{IVt:1ib}$\Rightarrow$\ref{IVt:1ic}: Clear by
\eqref{eKKnhf74g03}.

\ref{IVt:1ic}$\Rightarrow$\ref{IVt:1id}: In view of 
\eqref{IVe:Bfg+uh4f9-09h},
\begin{align}
0
&\ensuremath{\geqslant}\pair{x_n}{a_n^*+L^*b_n^*}
+\pair{b_n-La_n}{y_n^*}-\pair{a_n}{a_n^*}-\pair{b_n}{b_n^*}
\nonumber\\
&=\pair{x_n-a_n}{a_n^*+L^*y_n^*}+\pair{Lx_n-b_n}{b_n^*-y_n^*}
\nonumber\\
&=\gamma_n^{-1}\pair{x_n-a_n}{\nabla h(x_n)-\nabla h(a_n)}
+\mu_n^{-1}\pair{Lx_n-b_n}{\nabla j(Lx_n)-\nabla j(b_n)}.
\end{align}
Consequently, the strict monotonicity of $\nabla h$ and $\nabla j$ 
yields
\begin{equation}
x_n=a_n\quad\text{and}\quad Lx_n=b_n.
\end{equation}
Furthermore,
\begin{equation}
b_n^*=\mu_n^{-1}\big(\nabla j(Lx_n)-\nabla j(b_n)\big)+y_n^*
=\mu_n^{-1}\big(\nabla j(b_n)-\nabla j(b_n)\big)+y_n^*
=y_n^*.
\end{equation}

\ref{IVt:1id}$\Rightarrow$\ref{IVt:1ie}: We derive from 
\eqref{IVe:Bfg+uh4f9-09h} that
$a_n^*=\gamma_n^{-1}(\nabla h(x_n)-\nabla h(a_n))-L^*y_n^*
=-L^*y_n^*=-L^*b_n^*$. On the other hand, since
\begin{align}
\label{IWeQA8h33-30a}
\pair{La_n-b_n}{\nabla j(La_n)-\nabla j(b_n)}
&=\pair{Lx_n-b_n}{\nabla j(Lx_n)-\nabla j(b_n)}\nonumber\\
&=\mu_n\pair{Lx_n-b_n}{b_n^*-y_n^*}\nonumber\\
&=0,
\end{align}
the strict monotonicity of $\nabla j$ yields $La_n=b_n$.

\ref{IVt:1ie}$\Leftrightarrow$\ref{IVt:1if}: 
Proposition~\ref{ppOlk28ha12}\ref{ppOlk28ha12iia}.

\ref{IVt:1if}$\Rightarrow$\ref{IVt:1ig}: Indeed,
$\boldsymbol{x}_{n+1/2}=P_{\boldsymbol{H}_n}^{\boldsymbol{f}}
\boldsymbol{x}_n=\boldsymbol{x}_n$.

\ref{IVt:1ig}$\Rightarrow$\ref{IVt:1ih}: We have
\begin{equation}
\label{IWeQA8h33-30b}
\boldsymbol{x}_{n+1}=Q^{\boldsymbol{f}}(\boldsymbol{x}_0,
\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2})=
P^{\boldsymbol{f}}_{H^{\boldsymbol{f}}
(\boldsymbol{x}_0,\boldsymbol{x}_n)\cap H^{\boldsymbol{f}}
(\boldsymbol{x}_n,\boldsymbol{x}_{n+1/2})}
\boldsymbol{x}_0=P^{\boldsymbol{f}}_{H^{\boldsymbol{f}}
(\boldsymbol{x}_0,\boldsymbol{x}_n)}\boldsymbol{x}_0
=\boldsymbol{x}_n.
