\label{eKKnhf74g15b}
(a^*_n)_{n\in\ensuremath{\mathbb N}}\quad\text{and}\quad(b^*_n)_{n\in\ensuremath{\mathbb N}}
\quad\text{are bounded}.
\end{equation}
We therefore derive from 
\eqref{IVe:8re84}, \eqref{IVe:IV5}, \eqref{4:e18}, and 
\eqref{4:e19} that
\begin{equation}
\label{eKKnhf74g15h}
D^h(x_n,a_n)\to 0\quad\text{and}\quad
D^j(Lx_n,b_n)\to 0.
\end{equation}
Since $h$ and $j$ satisfy Condition~\ref{IVC:1}, we get
\begin{equation}
\label{IVe:IV10}
