where $\overline{\boldsymbol{x}}=(\overline{x},\overline{y}^*)$.
Hence, $D^{f}({x}_n,\overline{x})\to 0$, 
$D^{g^*}(y^*_n,\overline{y}^*)\to 0$, and, 
since $f$ and $g^*$ satisfy Condition~\ref{IVC:1}, we conclude
that $x_n\to\overline{x}$ and $y^*_n\to\overline{y}^*$.

Set 
$\boldsymbol{C}=\boldsymbol{Z}\cap\overline{\ensuremath{\text{\rm dom}\,}}\boldsymbol{f}$.
We first observe that, as in \eqref{eKKnhf74g15a}, 
\begin{equation}
\label{4eKKnhf74g20T}
(x_n)_{n\in\ensuremath{\mathbb N}}\in(\ensuremath{\text{\rm int\,dom}\,} f)^{\ensuremath{\mathbb N}}\quad\text{and}\quad
(y^*_n)_{n\in\ensuremath{\mathbb N}}\in(\ensuremath{\text{\rm int\,dom}\,} g^*)^{\ensuremath{\mathbb N}}\quad\text{are bounded}.
\end{equation}
In addition, we deduce from \eqref{eKKnhf74g05},
\eqref{eKKnhf74g04i}, and Proposition~\ref{p:2}\ref{p:2i-} that 
$\overline{\boldsymbol{x}}=(\overline{x},\overline{y}^*)\in
\boldsymbol{C}\subset\bigcap_{n\in\ensuremath{\mathbb N}}H^{\boldsymbol{f}}
(\boldsymbol{x}_0,\boldsymbol{x}_n)$, and hence from 
\eqref{eKKnhf74g19a} that
\begin{equation}
\label{4eKKnhf74g20u}
(\forall n\in\ensuremath{\mathbb N})\quad 
D^f(\overline{x},x_n)+D^{g^*}(\overline{y}^*,y_n^*)
=D^{\boldsymbol{f}}\big(\overline{\boldsymbol{x}},
\boldsymbol{x}_n\big)
\ensuremath{\leqslant} D^{\boldsymbol{f}}\big(\overline{\boldsymbol{x}},
\boldsymbol{x}_0\big).
\end{equation}
By virtue of Proposition~\ref{p:2}\ref{p:2iv} and 
\eqref{4eKKnhf74g20T}, it suffices to show that every cluster 
point of $(x_n,y_n^*)_{n\in\ensuremath{\mathbb N}}$ belongs to $\boldsymbol{Z}$. 
To this end, take $x\in\ensuremath{{\mathcal X}}$, $y^*\in\ensuremath{{\mathcal Y}}$, and 
a strictly increasing sequence $(k_n)_{n\in\ensuremath{\mathbb N}}$ in $\ensuremath{\mathbb N}$
such that $x_{k_n}\to x$ and $y_{k_n}^*\to y^*$. 
Then $Lx_{k_n}\to Lx$, $x\in\overline{\ensuremath{\text{\rm dom}\,}}f$, and 
$y^*\in\overline{\ensuremath{\text{\rm dom}\,}}g^*$. 
Since $\overline{x}\in\ensuremath{\text{\rm int\,dom}\,} f$ and since
\eqref{4eKKnhf74g20u} implies that 
$(D^f(\overline{x},x_{k_n}))_{n\in\ensuremath{\mathbb N}}$ is bounded,
it follows from Lemma~\ref{lkIuh727}\ref{lkIuh727i} that
$x\in\ensuremath{\text{\rm int\,dom}\,} f$. Analogously, $y^*\in\ensuremath{\text{\rm int\,dom}\,} g^*$. 
In turn, Lemma~\ref{lkIuh727}\ref{lkIuh727i--}
asserts that 
\begin{equation}
\label{4ekIuh725c}
\nabla f\big(x_{k_n}\big)\to\nabla f(x)
\quad\text{and}\quad 
\nabla g^*\big(y_{k_n}^*\big)\to\nabla g^*(y^*).
