we derive from \eqref{IVe:Bfg+uh4f9-09h} that
\begin{align}
\label{4ekIuh722a}
(\forall n\in\ensuremath{\mathbb N})\;\;
\sigma^{-1}D^h(\overline{x},a_{k_n})
&\ensuremath{\leqslant}\gamma_{k_n}^{-1}D^h(\overline{x},a_{k_n})\nonumber\\
&\ensuremath{\leqslant}\varepsilon^{-1}D^h(\overline{x},x_{k_n})+
\Pair{\overline{x}-a_{k_n}}{\gamma_{k_n}^{-1}\big(
\nabla h(x_{k_n})-\nabla h(a_{k_n})\big)}\nonumber\\
&=\varepsilon^{-1}D^h(\overline{x},x_{k_n})+
\pair{\overline{x}-a_{k_n}}{a^*_{k_n}+L^*y^*_{k_n}}\nonumber\\
&=\varepsilon^{-1}D^h(\overline{x},x_{k_n})+
\pair{\overline{x}-a_{k_n}}{a^*_{k_n}+L^*\overline{y}^*}
