Similarly,
\begin{align}
\label{4ekIuh722b}
(\forall n\in\ensuremath{\mathbb N})\quad 
\sigma^{-1}D^j(L\overline{x},b_{k_n})
&\ensuremath{\leqslant}\delta^{-1}D^j(L\overline{x},Lx_{k_n})
+\pair{L\overline{x}-b_{k_n}}{b_{k_n}^*-y_{k_n}^*}\nonumber\\
&\ensuremath{\leqslant}\delta^{-1}D^j(L\overline{x},Lx_{k_n})
+\pair{L\overline{x}-b_{k_n}}{b_{k_n}^*-\overline{y}^*}
