\end{equation}

Consider the primal problem
\begin{equation}
\label{4eKKnhf74g201}
\minimize{x_1\in\ensuremath{{\mathcal X}}_1,\ldots,\,x_m\in\ensuremath{{\mathcal X}}_m}{\sum_{i=1}^m
\varphi_i(x_i)+\sum_{k=1}^p 
\psi_k\bigg(\sum_{i=1}^mL_{ki}x_i\bigg)},
\end{equation}

Moreover, $f$ is G\^ateaux differentiable on $\ensuremath{\text{\rm int\:dom}f}\neq\ensuremath{{\varnothing}}$
and the associated \emph{Bregman distance} is 
\begin{equation}
\label{e:Bdist}
\begin{aligned}
D^f\colon\ensuremath{{\mathcal X}}\times\ensuremath{{\mathcal X}}&\to\,[0,\ensuremath{{+\infty}}]\\
(x,y)&\mapsto 
\begin{cases}
