\end{equation}
Therefore, since $\nabla h$ is uniformly continuous on every 
bounded subset of $\ensuremath{\text{\rm int\,dom}\,} h$ and $\nabla j$ is uniformly 
continuous on every bounded subset of $\ensuremath{\text{\rm int\,dom}\,} j$,
\begin{equation}
\label{IVe:IV12a}
\nabla h(x_n)-\nabla h(a_n)\to 0\quad\text{and}\quad
\nabla j(Lx_n)-\nabla j(b_n)\to 0.
\end{equation}
Hence, using \eqref{IVe:Bfg+uh4f9-09h}, we get
\begin{equation}
\label{IVe:IV13}
a_n^*+L^*y_n^*\to 0
\quad\text{and}\quad 
b_n^*-y_n^*\to 0.
\end{equation}
Now, let 
$\boldsymbol{x}=(x,y^*)\in\ensuremath{{\mathfrak W}}(\boldsymbol{x}_n)_{n\in\ensuremath{\mathbb N}}$,
say $\boldsymbol{x}_{k_n}\ensuremath{\:\rightharpoonup\:}\boldsymbol{x}$. 
Then $x_{k_n}\ensuremath{\:\rightharpoonup\:} x$ and $y_{k_n}^*\ensuremath{\:\rightharpoonup\:} y^*$, and we 
derive from \eqref{IVe:IV10} and \eqref{IVe:IV13} that
\begin{equation}
\label{IVe:IV11}
\begin{cases}
a_{k_n}\ensuremath{\:\rightharpoonup\:} x\\
b^*_{k_n}\ensuremath{\:\rightharpoonup\:} y^*
\end{cases}
\quad\text{and}\quad
\begin{cases}
La_{k_n}-b_{k_n}\to 0\\
a^*_{k_n}+L^*b^*_{k_n}\to 0.
\end{cases}
\end{equation}
It therefore follows from \eqref{eKKnhf74g04},
Proposition~\ref{ppOlk28ha12}\ref{ppOlk28ha12iii},
and \eqref{eKKnhf74g15a} that
$\boldsymbol{x}\in\boldsymbol{Z}\cap\overline{\ensuremath{\text{\rm dom}\,}}\boldsymbol{f}
=\boldsymbol{C}$. Hence, we derive from 
Proposition~\ref{p:2}\ref{p:2iv} that 
\begin{equation}
\label{eKKnhf74g15x}
D^{f}({x}_n,\overline{x})+D^{g^*}(y^*_n,\overline{y}^*)=
D^{\boldsymbol{f}}(\boldsymbol{x}_n,\overline{\boldsymbol{x}})\to 0,
\end{equation}
where $\overline{\boldsymbol{x}}=(\overline{x},\overline{y}^*)$.
Hence, $D^{f}({x}_n,\overline{x})\to 0$, 
$D^{g^*}(y^*_n,\overline{y}^*)\to 0$, and, 
since $f$ and $g^*$ satisfy Condition~\ref{IVC:1}, we conclude
that $x_n\to\overline{x}$ and $y^*_n\to\overline{y}^*$.
\end{proof}

\begin{remark}
\label{IVrKKnhf74g31}
We provide a couple of settings that satisfy the assumptions of
Theorem~\ref{IVt:1}.
\begin{enumerate}
\item
In Problem~\ref{prob:1}, suppose that $\ensuremath{{\mathcal X}}$ and $\ensuremath{{\mathcal Y}}$ are Hilbert 
spaces, that $f=\|\cdot\|^2/2$, and that $g=\|\cdot\|^2/2$.
Furthermore, in Theorem~\ref{IVt:1}, set $h=f$ and $j=g$, and note
that, for any $\varepsilon\in\ensuremath{\left]0,+\infty\right[}$, 
$\nabla h+\varepsilon A=\ensuremath{\operatorname{Id}}\,+\varepsilon A$ and 
$\nabla j+\varepsilon B=\ensuremath{\operatorname{Id}}\,+\varepsilon B$ are strongly monotone 
and hence coercive by Lemma~\ref{l:20}\ref{l:20ii}.
Then we recover the framework of \cite{Nfao15}, 
which has been applied to domain decomposition problems in 
\cite{Atto15}. 
\item
Let $(\Omega_1,\mathcal{F}_1,\mu_1)$ and
$(\Omega_2,\mathcal{F}_2,\mu_2)$ be measure spaces,
let $p$ and $q$ be in $\left]1,\ensuremath{{+\infty}}\right[$, and set
$p^*=p/(p-1)$ and $q^*=q/(q-1)$. In Problem~\ref{prob:1}, suppose 
that $\ensuremath{{\mathcal X}}=L^p(\Omega_1,\mathcal{F}_1,\mu_1)$, 
$\ensuremath{{\mathcal Y}}=L^q(\Omega_2,\mathcal{F}_2,\mu_2)$, $f=\|\cdot\|^p/p$, 
and $g=\|\cdot\|^q/q$. Then
$\ensuremath{{\mathcal X}}^*=L^{p^*}(\Omega_1,\mathcal{F}_1,\mu_1)$,
$\ensuremath{{\mathcal Y}}^*=L^{q^*}(\Omega_2,\mathcal{F}_2,\mu_2)$, and
$g^*=\|\cdot\|^{q^*}/q^*$. Moreover, 
it follows from Clarkson's theorem 
\cite[Theorem~II.4.7]{IVCi90_B} that $\ensuremath{{\mathcal X}}$, $\ensuremath{{\mathcal X}}^*$,
$\ensuremath{{\mathcal Y}}$, and $\ensuremath{{\mathcal Y}}^*$ are uniformly convex and uniformly smooth.
Hence, we derive from \cite[Corollary~5.5 and Example~6.5]{Ccm01} 
that $f$, $g$, and $g^*$ are Legendre functions which are 
uniformly convex on every bounded set, and which therefore 
satisfy Condition~\ref{IVC:1} by virtue of 
\cite[Example~4.10(i)]{Sico03}. 
Now set $h=f$ and $j=g$ in Theorem~\ref{IVt:1}.
We derive from 
\cite[Theorem~II.2.16(i)]{IVCi90_B} that $\nabla h$ and $\nabla j$ 
are uniformly continuous on every bounded subset of $\ensuremath{{\mathcal X}}$ and 
$\ensuremath{{\mathcal Y}}$, respectively. 
In addition, $h$ and $j$ are supercoercive and therefore,
for any $\varepsilon\in\ensuremath{\left]0,+\infty\right[}$, 
Proposition~\ref{IVpp:20a}\ref{IVcl:20b4} asserts that 
$\nabla h+\varepsilon A$ and $\nabla j+\varepsilon B$ are 
coercive. Finally, it follows from 
\cite[Proposition~II.4.9]{IVCi90_B} that
$\nabla h\colon x\mapsto |x|^{p-1}\ensuremath{\text{\rm sign}}(x)$ and 
$\nabla j\colon y\mapsto |y|^{q-1}\ensuremath{\text{\rm sign}}(y)$.
\end{enumerate}
\end{remark}

\begin{remark}
The implementation of algorithm \eqref{IVe:Bfg+uh4f9-09h}
requires the evaluation of the operator $(\nabla h+A)^{-1}$.
We provide a simple example in the Euclidean plane $\ensuremath{{\mathcal X}}$ of a
maximally monotone operator $A$ for which 
$(\nabla h+A)^{-1}$ can be computed explicitly, whereas
the classical resolvent $(\ensuremath{\operatorname{Id}}\,+A)^{-1}$ is difficult to evaluate.
Let $\beta\in\ensuremath{\left]0,+\infty\right[}$ and let $\psi\colon\ensuremath{\mathbb{R}}\to\ensuremath{\mathbb{R}}$ be a Legendre 
function with a $\beta$ Lipschitz-continuous derivative.
Set
\begin{equation}
A\colon\ensuremath{\mathbb{R}}^2\to\ensuremath{\mathbb{R}}^2\colon (\xi_1,\xi_2)\mapsto
\big(\beta\xi_1-\psi'(\xi_1)-\xi_2,
\xi_1+\beta\xi_2-\psi'(\xi_2)\big)
\end{equation}
and 
\begin{equation}
h\colon\ensuremath{\mathbb{R}}^2\to\ensuremath{\left]-\infty,+\infty\right]}\colon (\xi_1,\xi_2)\mapsto
\psi(\xi_1)+\psi(\xi_2).
\end{equation}
Then it follows from \cite[Theorem~18.15]{Livre1} that $A$ is the
sum of the gradient of the convex function 
$(\xi_1,\xi_2)\mapsto\beta\xi_1^2/2-\psi(\xi_1)+
\beta\xi_2^2/2-\psi(\xi_2)$ 
and of the skew linear operator $(\xi_1,\xi_2)\mapsto(-\xi_2,\xi_1)$.
Thus, $A$ is a maximally monotone operator 
\cite[Corollary~24.4]{Livre1} which is not the
subdifferential of a convex function. In addition, as in 
Proposition~\ref{pvb8uh4504}\ref{pvb8uh4504i},
$h$ is a Legendre function and
\begin{equation}
\big(\forall (\xi_1,\xi_2)\in\ensuremath{\mathbb{R}}^2\big)\quad 
(\nabla h+A)^{-1}(\xi_1,\xi_2)
=\Bigg(\dfrac{\beta\xi_1+\xi_2}{1+\beta^2},
\dfrac{\beta\xi_2-\xi_1}{1+\beta^2}\Bigg).
\end{equation}
\end{remark}

\begin{remark}
\label{rvb8uh4504}
At every iteration $n$, algorithm \eqref{IVe:Bfg+uh4f9-09h}
requires the computation of $\boldsymbol{x}_{n+1/2}=
P_{\boldsymbol{H}_n}^{\boldsymbol{f}}(x_n,y_n^*)$ and then of
$\boldsymbol{x}_{n+1}=Q^{\boldsymbol{f}}((x_0,y_0^*),(x_n,y_n^*),
(x_{n+1/2},y_{n+1/2}^*))$. 
Set $\boldsymbol{s}_n^*=(a_n^*+L^*b_n^*,b_n-La_n)$, 
$\eta_n=\pair{a_n}{a_n^*}+\pair{b_n}{b_n^*}$, and
$\boldsymbol{x}_n=(x_n,y_n^*)$,
Then, if $\boldsymbol{x}_n\not\in\boldsymbol{H}_n$, 
$\boldsymbol{x}_{n+1/2}$ is the Bregman projection of 
$\boldsymbol{x}_n$ onto the closed affine 
hyperplane $\menge{\boldsymbol{x}\in\ensuremath{\boldsymbol{\mathcal X}}}
{\pair{\boldsymbol{x}}{\boldsymbol{s}_n^*}=\eta_n}$. Thus,
$\boldsymbol{x}_{n+1/2}$ is the solution of the problem 
\begin{equation}
\label{evb8uh4505a}
\minimize{\pair{\boldsymbol{p}}{\boldsymbol{s}_n^*}=\eta_n}
{\boldsymbol{f}(\boldsymbol{p})-\pair{\boldsymbol{p}}{\nabla
\boldsymbol{f}(\boldsymbol{x}_n)}}
\end{equation}
which, using standard first order conditions, is characterized by
(see also \cite[Remark~6.13]{BB97} and 
\cite[Lemma~2.2.1]{Cens97}) 
\begin{equation}
\label{evb8uh4505b}
\begin{cases}
\nabla\boldsymbol{f}(\boldsymbol{x}_{n+1/2})=\nabla
\boldsymbol{f}(\boldsymbol{x}_n)-\lambda\boldsymbol{s}_n^*\\
\pair{\boldsymbol{x}_{n+1/2}}{\boldsymbol{s}_n^*}=\eta_n\\
\lambda\in\ensuremath{\left]0,+\infty\right[}.
\end{cases}
\end{equation}
In view of \cite[Theorem~5.10]{Ccm01}, the Lagrange multiplier 
$\lambda$ is uniquely determined by the equation 
$\pair{\nabla\boldsymbol{f}^*(\nabla\boldsymbol{f}
(\boldsymbol{x}_n)-\lambda\boldsymbol{s}_n^*)}
{\boldsymbol{s}_n^*}=\eta_n$. The problem therefore reduces to
finding the solution $\overline{\lambda}$ to this equation in $\ensuremath{\left]0,+\infty\right[}$
and then setting $\boldsymbol{x}_{n+1/2}=\nabla\boldsymbol{f}^*(
\nabla\boldsymbol{f}(\boldsymbol{x}_n)-\overline{\lambda}
\boldsymbol{s}_n^*)$. Likewise, it follows from \eqref{e:Q} that 
$\boldsymbol{x}_{n+1}$ is the unique solution to the problem 
\begin{equation}
\label{evb8uh4505c}
\minimize{\substack{\pair{\boldsymbol{p}-\boldsymbol{x}_n}
{\nabla\boldsymbol{f}(\boldsymbol{x}_0)-
\nabla\boldsymbol{f}(\boldsymbol{x}_n)}\ensuremath{\leqslant} 0\\
\pair{\boldsymbol{p}-\boldsymbol{x}_{n+1/2}}
{\nabla\boldsymbol{f}(\boldsymbol{x}_{n})-
\nabla\boldsymbol{f}(\boldsymbol{x}_{n+1/2})}\ensuremath{\leqslant} 0}}
{\boldsymbol{f}(\boldsymbol{p})-\pair{\boldsymbol{p}}{\nabla
\boldsymbol{f}(\boldsymbol{x}_0)}}.
\end{equation}
Depending on the number of active constraints, this 
problem boils down to determining 
up to two Lagrange multipliers in $\ensuremath{\left]0,+\infty\right[}$.
\end{remark}

Next, we consider a specialization of Problem~\ref{prob:1} to
multivariate structured minimization.

\begin{problem}
\label{IVpb:V3}
Let $m$ and $p$ be strictly positive integers, let
$(\ensuremath{{\mathcal X}}_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}$ and $(\ensuremath{{\mathcal Y}}_k)_{1\ensuremath{\leqslant} k\ensuremath{\leqslant} p}$ be 
reflexive real Banach spaces, and let 
$\boldsymbol{\ensuremath{{\mathcal X}}}$ be the standard vector product space 
$\Big(\ensuremath{\raisebox{-0.5mm}{\mbox{\huge{$\times$}}}}_{\!\!i=1}^{\!\!m}\ensuremath{{\mathcal X}}_i\Big)\times
\Big(\ensuremath{\raisebox{-0.5mm}{\mbox{\huge{$\times$}}}}_{\!\!k=1}^{\!\!p}\ensuremath{{\mathcal Y}}_k^*\Big)$ 
equipped with the norm 
\begin{equation}
(x,y^*)=\big((x_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m},(y_k^*)_{1\ensuremath{\leqslant} k\ensuremath{\leqslant} p}\big)
\mapsto\sqrt{\sum_{i=1}^m\|x_i\|^2+\sum_{k=1}^p\|y_k^*\|^2}.
\end{equation} 
For every $i\in\{1,\ldots,m\}$ and every $k\in\{1,\ldots,p\}$, 
let $\varphi_i\in\Gamma_0(\ensuremath{{\mathcal X}}_i)$, let $\psi_k\in\Gamma_0(\ensuremath{{\mathcal Y}}_k)$,
and let $L_{ki}\colon\ensuremath{{\mathcal X}}_i\to\ensuremath{{\mathcal Y}}_k$ be linear and bounded. 
Consider the primal problem 
\begin{equation}
\label{4eKKnhf74g201}
\minimize{x_1\in\ensuremath{{\mathcal X}}_1,\ldots,\,x_m\in\ensuremath{{\mathcal X}}_m}{\sum_{i=1}^m
\varphi_i(x_i)+\sum_{k=1}^p 
\psi_k\bigg(\sum_{i=1}^mL_{ki}x_i\bigg)},
\end{equation}
the dual problem
\begin{equation}
\label{4eKKnhf74g202}
\minimize{y^*_1\in\ensuremath{{\mathcal Y}}_1^*,\ldots,\,y^*_p\in\ensuremath{{\mathcal Y}}_p^*}{\sum_{i=1}^m
\varphi_i^*\bigg(-\sum_{k=1}^pL_{ki}^*y^*_k\bigg)
+\sum_{k=1}^p\psi^*_k(y^*_k)}, 
\end{equation}
and let 
\begin{multline}
\boldsymbol{Z}=\bigg\{({x},{y}^*)
\in\boldsymbol{\mathcal{X}}\;\bigg |\;
(\forall i\in\{1,\ldots,m\})\;\;-\sum_{k=1}^pL_{ki}^*y_k^*
\in\partial\varphi_i(x_i)\:\;\text{and}\\
(\forall k\in\{1,\ldots,p\})\;\;\sum_{i=1}^mL_{ki}x_i\in
\partial\psi_k^*(y_k^*)\bigg\}
\end{multline}
be the associated Kuhn-Tucker set. For every $i\in\{1,\ldots,m\}$,
let $f_i\in\Gamma_0(\ensuremath{{\mathcal X}}_i)$ be a Legendre function and let
$x_{i,0}\in\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,} f_i$. For every $k\in\{1,\ldots,p\}$, 
let $g_k\in\Gamma_0(\ensuremath{{\mathcal Y}}_k)$ be a Legendre function and let
$y^*_{k,0}\in\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,} g^*_k$. Set
${x}_0=(x_{i,0})_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}$, 
${y}_0^*=(y_{k,0}^*)_{1\ensuremath{\leqslant} k\ensuremath{\leqslant} p}$, and 
\begin{equation}
\boldsymbol{f}\colon\boldsymbol{\ensuremath{{\mathcal X}}}\to\ensuremath{\left]-\infty,+\infty\right]}\colon
({x},{y}^*)\mapsto
\sum_{i=1}^mf_i(x_i)+\sum_{k=1}^pg_k^*(y_k^*),
\end{equation}
and suppose that 
$\boldsymbol{Z}\cap\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,}\boldsymbol{f}\neq\ensuremath{{\varnothing}}$. 
The objective is to find the best Bregman approximation 
$\big((\overline{x}_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m},
(\overline{y}_k^*)_{1\ensuremath{\leqslant} k\ensuremath{\leqslant} p}\big)
=P_{\boldsymbol{Z}}^{\boldsymbol{f}} ({x}_0,{y}_0^*)$ 
to $({x}_0,{y}_0^*)$ from $\boldsymbol{Z}$.
\end{problem}

We derive from Theorem~\ref{IVt:1} the following convergence
result for a splitting algorithm to solve Problem~\ref{IVpb:V3}.

\begin{proof}
Set 
$\boldsymbol{C}=\boldsymbol{Z}\cap\overline{\ensuremath{\text{\rm dom}\,}}\boldsymbol{f}$.
We first observe that, as in \eqref{eKKnhf74g15a}, 
\begin{equation}
\label{4eKKnhf74g20T}
(x_n)_{n\in\ensuremath{\mathbb N}}\in(\ensuremath{\text{\rm int\,dom}\,} f)^{\ensuremath{\mathbb N}}\quad\text{and}\quad
(y^*_n)_{n\in\ensuremath{\mathbb N}}\in(\ensuremath{\text{\rm int\,dom}\,} g^*)^{\ensuremath{\mathbb N}}\quad\text{are bounded}.
\end{equation}
In addition, we deduce from \eqref{eKKnhf74g05},
\eqref{eKKnhf74g04i}, and Proposition~\ref{p:2}\ref{p:2i-} that 
$\overline{\boldsymbol{x}}=(\overline{x},\overline{y}^*)\in
\boldsymbol{C}\subset\bigcap_{n\in\ensuremath{\mathbb N}}H^{\boldsymbol{f}}
(\boldsymbol{x}_0,\boldsymbol{x}_n)$, and hence from 
\eqref{eKKnhf74g19a} that
\begin{equation}
\label{4eKKnhf74g20u}
(\forall n\in\ensuremath{\mathbb N})\quad 
D^f(\overline{x},x_n)+D^{g^*}(\overline{y}^*,y_n^*)
=D^{\boldsymbol{f}}\big(\overline{\boldsymbol{x}},
\boldsymbol{x}_n\big)
\ensuremath{\leqslant} D^{\boldsymbol{f}}\big(\overline{\boldsymbol{x}},
\boldsymbol{x}_0\big).
\end{equation}
By virtue of Proposition~\ref{p:2}\ref{p:2iv} and 
\eqref{4eKKnhf74g20T}, it suffices to show that every cluster 
point of $(x_n,y_n^*)_{n\in\ensuremath{\mathbb N}}$ belongs to $\boldsymbol{Z}$. 
To this end, take $x\in\ensuremath{{\mathcal X}}$, $y^*\in\ensuremath{{\mathcal Y}}$, and 
a strictly increasing sequence $(k_n)_{n\in\ensuremath{\mathbb N}}$ in $\ensuremath{\mathbb N}$
such that $x_{k_n}\to x$ and $y_{k_n}^*\to y^*$. 
Then $Lx_{k_n}\to Lx$, $x\in\overline{\ensuremath{\text{\rm dom}\,}}f$, and 
$y^*\in\overline{\ensuremath{\text{\rm dom}\,}}g^*$. 
Since $\overline{x}\in\ensuremath{\text{\rm int\,dom}\,} f$ and since
\eqref{4eKKnhf74g20u} implies that 
$(D^f(\overline{x},x_{k_n}))_{n\in\ensuremath{\mathbb N}}$ is bounded,
it follows from Lemma~\ref{lkIuh727}\ref{lkIuh727i} that
$x\in\ensuremath{\text{\rm int\,dom}\,} f$. Analogously, $y^*\in\ensuremath{\text{\rm int\,dom}\,} g^*$. 
In turn, Lemma~\ref{lkIuh727}\ref{lkIuh727i--}
asserts that 
\begin{equation}
\label{4ekIuh725c}
\nabla f\big(x_{k_n}\big)\to\nabla f(x)
\quad\text{and}\quad 
\nabla g^*\big(y_{k_n}^*\big)\to\nabla g^*(y^*).
\end{equation}
Furthermore, since $\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,} f\subset\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,} h$ 
and $L(\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,} f)\subset\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,} j$, we obtain
$x\in\ensuremath{\text{\rm int\,dom}\,} h$ and $Lx\in\ensuremath{\text{\rm int\,dom}\,} j$. Thus, there exists 
$\rho\in\ensuremath{\left]0,+\infty\right[}$ such that $B(x;\rho)\subset\ensuremath{\text{\rm int\,dom}\,} h$ and
$B(Lx;\rho)\subset\ensuremath{\text{\rm int\,dom}\,} j$.
We therefore assume without loss of generality that 
\begin{equation}
\label{4ekIuh716a}
(x_{k_n})_{n\in\ensuremath{\mathbb N}}\in B(x;\rho)^{\ensuremath{\mathbb N}}
\quad\text{and}\quad 
(Lx_{k_n})_{n\in\ensuremath{\mathbb N}}\in B(Lx;\rho)^{\ensuremath{\mathbb N}}.
\end{equation}
In view of Lemma~\ref{lkIuh727}\ref{lkIuh727i--},
$h({B(x;\rho)})$ and $\nabla h({B(x;\rho)})$ are therefore compact,
which implies that $(h(x_{k_n}))_{n\in\ensuremath{\mathbb N}}$ and 
$(\nabla h(x_{k_n}))_{n\in\ensuremath{\mathbb N}}$ are bounded. 
Hence $(D^h(\overline{x},x_{k_n}))_{n\in\ensuremath{\mathbb N}}$ is bounded and, 
moreover, it follows from \eqref{IVe:Bfg+uh4f9-09h}, 
\eqref{4eKKnhf74g20T}, Lemma~\ref{IVlKKnhf74g12}, 
and \eqref{4:e12} that $(a_{k_n})_{n\in\ensuremath{\mathbb N}}$ 
is a bounded sequence in $\ensuremath{\text{\rm int\,dom}\,} h$. 
We show likewise that $(D^j(L\overline{x},Lx_{k_n}))_{n\in\ensuremath{\mathbb N}}$ 
and $(b_{k_n})_{n\in\ensuremath{\mathbb N}}$ are bounded. 
Next, since the convexity of $h$ yields 
\begin{align}
(\forall n\in\ensuremath{\mathbb N})\;\;
D^h(\overline{x},a_{k_n})
&=h(\overline{x})-h(a_{k_n})-\pair{\overline{x}-a_{k_n}}
{\nabla h(a_{k_n})}\nonumber\\
&=h(\overline{x})-h(x_{k_n})-\pair{\overline{x}-x_{k_n}}
{\nabla h(x_{k_n})}+\Pair{\overline{x}-a_{k_n}}
{\nabla h(x_{k_n})-\nabla h(a_{k_n})}\nonumber\\
&\quad\;-\big(h(a_{k_n})-h(x_{k_n})-\pair{a_{k_n}-x_{k_n}}
{\nabla h(x_{k_n})}\big)\nonumber\\
&\ensuremath{\leqslant} D^h(\overline{x},x_{k_n})+\Pair{\overline{x}-a_{k_n}}
{\nabla h(x_{k_n})-\nabla h(a_{k_n})},
\end{align}
we derive from \eqref{IVe:Bfg+uh4f9-09h} that
\begin{align}
\label{4ekIuh722a}
(\forall n\in\ensuremath{\mathbb N})\;\;
\sigma^{-1}D^h(\overline{x},a_{k_n})
&\ensuremath{\leqslant}\gamma_{k_n}^{-1}D^h(\overline{x},a_{k_n})\nonumber\\
&\ensuremath{\leqslant}\varepsilon^{-1}D^h(\overline{x},x_{k_n})+
\Pair{\overline{x}-a_{k_n}}{\gamma_{k_n}^{-1}\big(
\nabla h(x_{k_n})-\nabla h(a_{k_n})\big)}\nonumber\\
&=\varepsilon^{-1}D^h(\overline{x},x_{k_n})+
\pair{\overline{x}-a_{k_n}}{a^*_{k_n}+L^*y^*_{k_n}}\nonumber\\
&=\varepsilon^{-1}D^h(\overline{x},x_{k_n})+
\pair{\overline{x}-a_{k_n}}{a^*_{k_n}+L^*\overline{y}^*}
\nonumber\\
&\quad\;+\pair{L\overline{x}-La_{k_n}}{y^*_{k_n}-\overline{y}^*}.
\end{align}
Similarly,
\begin{align}
\label{4ekIuh722b}
(\forall n\in\ensuremath{\mathbb N})\quad 
\sigma^{-1}D^j(L\overline{x},b_{k_n})
&\ensuremath{\leqslant}\delta^{-1}D^j(L\overline{x},Lx_{k_n})
+\pair{L\overline{x}-b_{k_n}}{b_{k_n}^*-y_{k_n}^*}\nonumber\\
&\ensuremath{\leqslant}\delta^{-1}D^j(L\overline{x},Lx_{k_n})
+\pair{L\overline{x}-b_{k_n}}{b_{k_n}^*-\overline{y}^*}
\nonumber\\
&\quad\;+\pair{L\overline{x}-b_{k_n}}{\overline{y}^*-y_{k_n}^*}.
\end{align}
Since \eqref{eKKnhf74g03} entails that
\begin{equation}
\label{ekIuh725a}
\overline{\boldsymbol{x}}\in\boldsymbol{C}\subset
\bigcap_{n\in\ensuremath{\mathbb N}}\boldsymbol{H}_{k_n}=
\bigcap_{n\in\ensuremath{\mathbb N}}\menge{(x,y^*)\in\ensuremath{\boldsymbol{\mathcal X}}}
{\pair{x-a_{k_n}}{a_{k_n}^*+L^*y^*}+
\pair{Lx-b_{k_n}}{b_{k_n}^*-y^*}\ensuremath{\leqslant} 0},
\end{equation}
we deduce from \eqref{4ekIuh722a} and 
\eqref{4ekIuh722b} that
\begin{align}
&\hskip -6mm (\forall n\in\ensuremath{\mathbb N})\quad
\sigma^{-1}\big(D^h(\overline{x},a_{k_n})
+D^j(L\overline{x},b_{k_n})\big)\nonumber\\
&\ensuremath{\leqslant}\varepsilon^{-1}D^h(\overline{x},x_{k_n})
+\delta^{-1}D^j(L\overline{x},Lx_{k_n})
+\pair{L\overline{x}-La_{k_n}}{y^*_{k_n}-\overline{y}^*}
+\pair{L\overline{x}-b_{k_n}}{\overline{y}^*-y_{k_n}^*}
\nonumber\\
&=\varepsilon^{-1}D^h(\overline{x},x_{k_n})
+\delta^{-1}D^j(L\overline{x},Lx_{k_n})
+\pair{b_{k_n}-La_{k_n}}{y^*_{k_n}-\overline{y}^*}
\nonumber\\
&\ensuremath{\leqslant}\varepsilon^{-1}D^h(\overline{x},x_{k_n})
+\delta^{-1}D^j(L\overline{x},Lx_{k_n})
+(\|b_{k_n}\|+\|L\|\,\|a_{k_n}\|)(\|y^*_{k_n}\|+\|\overline{y}^*\|).
\end{align}
Hence, the boundedness of $(a_{k_n})_{n\in\ensuremath{\mathbb N}}$, 
$(b_{k_n})_{n\in\ensuremath{\mathbb N}}$, $(y^*_{k_n})_{n\in\ensuremath{\mathbb N}}$, 
$(D^h(\overline{x},x_{k_n}))_{n\in\ensuremath{\mathbb N}}$, 
and $(D^j(L\overline{x},Lx_{k_n}))_{n\in\ensuremath{\mathbb N}}$ implies that of
$(D^h(\overline{x},a_{k_n}))_{n\in\ensuremath{\mathbb N}}$ and 
$(D^j(L\overline{x},b_{k_n}))_{n\in\ensuremath{\mathbb N}}$.
In turn, by Lemma~\ref{lkIuh727}\ref{lkIuh727iv},
\begin{equation}
\label{4ekIuh722c}
\Big(D^{h^*}\big(\nabla h(a_{k_n}),
\nabla h(\overline{x})\big)\Big)_{n\in\ensuremath{\mathbb N}}
\quad\text{and}\quad
\Big(D^{j^*}\big(\nabla j(b_{k_n}),
\nabla j(L\overline{x})\big)\Big)_{n\in\ensuremath{\mathbb N}}
\quad\text{are bounded}
\end{equation}
and, since Lemma~\ref{lkIuh727}\ref{lkIuh727iii} asserts 
that $D^{h^*}(\cdot,\nabla h(\overline{x}))$ 
and $D^{j^*}(\cdot,\nabla j(L\overline{x}))$ are coercive, 
it follows from \eqref{4ekIuh722c} that 
$(\nabla h(a_{k_n}))_{n\in\ensuremath{\mathbb N}}$ 
and $(\nabla j(b_{k_n}))_{n\in\ensuremath{\mathbb N}}$ are bounded. 
Thus, since $(y^*_{k_n})_{n\in\ensuremath{\mathbb N}}$, $(\nabla h(x_{k_n}))_{n\in\ensuremath{\mathbb N}}$ 
and $(\nabla j(Lx_{k_n}))_{n\in\ensuremath{\mathbb N}}$ are bounded, 
we infer from \eqref{IVe:Bfg+uh4f9-09h} that 
\begin{equation}
\label{4ekIuh726a}
(a_{k_n}^*)_{n\in\ensuremath{\mathbb N}}\quad\text{and}\quad (b_{k_n}^*)_{n\in\ensuremath{\mathbb N}}
\quad\text{are bounded.}
\end{equation}
On the other hand, since \eqref{eKKnhf74g03} yields
$\overline{\boldsymbol{x}}\in\boldsymbol{C}
\subset\bigcap_{n\in\ensuremath{\mathbb N}}H^{\boldsymbol{f}}(\boldsymbol{x}_{k_n},
\boldsymbol{x}_{k_n+1/2})$, \eqref{eKKnhf74g19a} and
\eqref{4eKKnhf74g20u} imply that 
\begin{equation}
\label{4ekIuh726d}
(\forall n\in\ensuremath{\mathbb N})\quad D^f(\overline{x},x_{k_n+1/2})
+D^{g^*}(\overline{y}^*,y_{k_n+1/2}^*)
=D^{\boldsymbol{f}}\big(\overline{\boldsymbol{x}},
\boldsymbol{x}_{k_n+1/2}\big)
\ensuremath{\leqslant} D^{\boldsymbol{f}}\big(\overline{\boldsymbol{x}},
\boldsymbol{x}_{k_n}\big)\ensuremath{\leqslant} 
D^{\boldsymbol{f}}\big(\overline{\boldsymbol{x}},
\boldsymbol{x}_0\big).
\end{equation}
Thus, Lemma~\ref{lkIuh727}\ref{lkIuh727iv} yields
\begin{align}
\label{4ekIuh727d}
& (\forall n\in\ensuremath{\mathbb N})\quad 
D^{f^*}\big(\nabla f(x_{k_n+1/2}),
\nabla f(\overline{x})\big)+D^g\big(\nabla g^*(y_{k_n+1/2}^*),
\nabla g^*(\overline{y}^*)\big)\nonumber\\
&\hskip 32mm=D^f(\overline{x},x_{k_n+1/2})
+D^{g^*}(\overline{y}^*,y_{k_n+1/2}^*)\nonumber\\
&\hskip 32mm\ensuremath{\leqslant} D^{\boldsymbol{f}}\big(\overline{\boldsymbol{x}},
\boldsymbol{x}_0\big)
\end{align}
and, since $D^{f^*}(\cdot,\nabla f(\overline{x}))$ and
$D^g(\cdot,\nabla g^*(\overline{y}^*))$ are coercive by
Lemma~\ref{lkIuh727}\ref{lkIuh727iii}, it follows that
\begin{equation}
\label{4ekIuh724}
(\nabla f(x_{k_n+1/2}))_{n\in\ensuremath{\mathbb N}}\quad\text{and}\quad
(\nabla g^*(y_{k_n+1/2}^*))_{n\in\ensuremath{\mathbb N}}
\quad\text{are bounded.}
\end{equation}
However, as in \eqref{IVe:IV4}, 
$D^f(x_{k_n+1/2},x_{k_n})\to 0$ and 
$D^{g^*}(y_{k_n+1/2}^*,y_{k_n}^*)\to 0$, and it therefore follows 
from Lemma~\ref{lkIuh727}\ref{lkIuh727iv} that
\begin{equation}
\label{4ekIuh725a}
D^{f^*}\big(\nabla f(x_{k_n}),\nabla f(x_{k_n+1/2})\big)\to 0
\quad\text{and}\quad 
D^g\big(\nabla g^*(y_{k_n}^*),\nabla g^*(y_{k_n+1/2}^*)\big)\to 0.
\end{equation} 
In view of Lemma~\ref{lkIuh727}\ref{lkIuh727ii}, we infer 
from \eqref{4ekIuh725c}, \eqref{4ekIuh724}, and 
\eqref{4ekIuh725a} that there exists a strictly increasing 
sequence $(p_{k_n})_{n\in\ensuremath{\mathbb N}}$ in $\ensuremath{\mathbb N}$ such that
\begin{equation}
\nabla f\big(x_{p_{k_n}+1/2}\big)\to\nabla f(x)
\quad\text{and}\quad 
\nabla g^*\big(y_{p_{k_n}+1/2}^*\big)\to\nabla g^*(y^*).
\end{equation}
Since, by Lemma~\ref{lkIuh727}\ref{lkIuh727i--}--
\ref{lkIuh727i-},
$(\nabla f)^{-1}=\nabla f^*$ is continuous on
$\ensuremath{\text{\rm int\,dom}\,} f^*$ and $(\nabla g^*)^{-1}=\nabla g$ is continuous on
$\ensuremath{\text{\rm int\,dom}\,} g$, we obtain $x_{p_{k_n}+1/2}\to x$ and 
$y_{p_{k_n}+1/2}^*\to y^*$. Thus, 
\begin{equation}
\label{4ekIuh725b}
x_{p_{k_n}+1/2}-x_{p_{k_n}}\to 0
\quad\text{and}\quad 
y_{p_{k_n}+1/2}^*-y_{p_{k_n}}^*\to 0.
\end{equation}
On the other hand, as in \eqref{IVe:8re84},
\begin{multline}
(\forall n\in\ensuremath{\mathbb N})\quad
\|x_{p_{k_n}}-x_{p_{k_n}+1/2}\|\,
\|a_{p_{k_n}}^*+L^*b_{p_{k_n}}^*\|
+\|b_{p_{k_n}}-La_{p_{k_n}}\|\,
\|y_{p_{k_n}}^*-y_{p_{k_n}+1/2}^*\|\\
\ensuremath{\geqslant}\sigma^{-1}\big(D^h(x_{p_{k_n}},a_{p_{k_n}})
+D^j(Lx_{p_{k_n}},b_{p_{k_n}})\big),
\end{multline}
and hence, since $(a_{p_{k_n}})_{n\in\ensuremath{\mathbb N}}$ and 
$(b_{p_{k_n}})_{n\in\ensuremath{\mathbb N}}$ are bounded, 
we deduce from \eqref{4ekIuh726a} and 
\eqref{4ekIuh725b} that
\begin{equation}
\label{4eKKnhf74g2022a}
\begin{cases}
D^h\big(x_{p_{k_n}},a_{p_{k_n}}\big)\to 0\\
D^j\big(Lx_{p_{k_n}},b_{p_{k_n}}\big)\to 0\\
x_{p_{k_n}}\to x\\
Lx_{p_{k_n}}\to Lx\\
(a_{p_{k_n}})_{n\in\ensuremath{\mathbb N}}\;\text{has a cluster point}\\
(b_{p_{k_n}})_{n\in\ensuremath{\mathbb N}}\;\text{has a cluster point}.
\end{cases}
\end{equation}
Consequently, by dropping to a subsequence if necessary and invoking 
Lemma~\ref{lkIuh727}\ref{lkIuh727ii}, we get
\begin{equation}
a_{{p_{k_n}}}\to x\quad\text{and}\quad b_{{p_{k_n}}}\to Lx.
\end{equation}
Hence, using the fact that $\nabla h(x_{{p_{k_n}}})\to\nabla h(x)$ 
and $\nabla j(Lx_{{p_{k_n}}})\to\nabla j(Lx)$, we derive that
$\nabla h(x_{{p_{k_n}}})-\nabla h(a_{{p_{k_n}}})\to 0$ 
and $\nabla j(Lx_{{p_{k_n}}})-\nabla j(b_{{p_{k_n}}})\to 0$, 
which, in view of \eqref{IVe:Bfg+uh4f9-09h}, yields
\begin{equation}
\label{4ekIuh711f}
a^*_{{p_{k_n}}}+L^*y^*_{{p_{k_n}}}\to 0
\quad\text{and}\quad
b^*_{{p_{k_n}}}-y_{{p_{k_n}}}^*\to 0.
\end{equation}
Thus, since $y_{{p_{k_n}}}^*\to y^*$, it follows that 
$a_{{p_{k_n}}}^*\to -L^*y^*$ and $b_{{p_{k_n}}}^*\to y^*$. 
In summary,
\begin{equation}
\ensuremath{\text{\rm gra}\,} A\ni(a_{{p_{k_n}}},a_{{p_{k_n}}}^*)\to (x,-L^*y^*)
\quad\text{and}\quad
\ensuremath{\text{\rm gra}\,} B\ni(b_{{p_{k_n}}},b_{{p_{k_n}}}^*)\to (Lx,y^*).
\end{equation}
Since $\ensuremath{\text{\rm gra}\,} A$ and $\ensuremath{\text{\rm gra}\,} B$ are closed 
\cite[Proposition~20.33(iii)]{Livre1}, we conclude that
$(x,-L^*y^*)\in\ensuremath{\text{\rm gra}\,} A$ and $(Lx,y^*)\in\ensuremath{\text{\rm gra}\,} B$, and therefore
that $(x,y^*)\in\boldsymbol{Z}$.
\end{proof}

Let us note that, even in Euclidean spaces, it may be easier to 
evaluate $(\nabla h+\gamma\partial\varphi)^{-1}$ than the usual 
proximity operator
$\ensuremath{\text{\rm prox}}_{\gamma\varphi}=(\ensuremath{\operatorname{Id}}\,+\gamma\partial\varphi)^{-1}$ 
introduced by Moreau \cite{Mor62b}, which is
based on $h=\|\cdot\|^2/2$. We provide illustrations of such 
instances in the standard Euclidean space $\ensuremath{\mathbb{R}}^m$.

\begin{example}
\label{IVex:1}
Let $\gamma\in\ensuremath{\left]0,+\infty\right[}$, let $\phi\in\Gamma_0(\ensuremath{\mathbb{R}})$ be such that 
$\ensuremath{\text{\rm dom}\,}\phi\cap\ensuremath{\left]0,+\infty\right[}\neq\ensuremath{{\varnothing}}$, and let $\vartheta$ be the 
Boltzmann-Shannon entropy function, i.e.,
\begin{equation}
\vartheta\colon\xi\mapsto
\begin{cases}
\xi\ln\xi-\xi,&\text{if}\;\;\xi\in\ensuremath{\left]0,+\infty\right[};\\
0,&\text{if}\;\;\xi=0;\\
\ensuremath{{+\infty}},&\text{otherwise}.
\end{cases}
\end{equation}
Set $\varphi\colon(\xi_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}\mapsto
\sum_{i=1}^m\phi(\xi_i)$ and $h\colon(\xi_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}
\mapsto\sum_{i=1}^m\vartheta(\xi_i)$. Note that $h$ is a 
supercoercive Legendre function \cite[Sections~5 and 6]{BB97} 
and hence Proposition~\ref{IVpp:20a}\ref{IVcl:20b4} asserts 
that $\nabla h+\gamma\partial\varphi$ is coercive and 
$\ensuremath{\text{\rm dom}\,}(\nabla h+\gamma\partial\varphi)^{-1}=\ensuremath{\mathbb{R}}^m$. 
Now let $(\xi_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}\in\ensuremath{\mathbb{R}}^m$, set 
$(\eta_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}
=(\nabla h+\gamma\partial\varphi)^{-1}(\xi_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}$, 
let $W$ be the Lambert function \cite{IVlamb96,Lamb58}, 
i.e., the inverse of $\xi\mapsto\xi e^{\xi}$ on $\ensuremath{\left[0,+\infty\right[}$, 
and let $i\in\{1,\ldots,m\}$. Then $\eta_i$ can be computed 
as follows.
\begin{enumerate}
\item
\label{IVex:1ii}
Let $\omega\in\ensuremath{\mathbb{R}}$ and suppose that 
\begin{equation}
\phi\colon\xi\mapsto
\begin{cases}
\xi\ln\xi-\omega\xi,&\text{if}\;\;\xi\in\ensuremath{\left]0,+\infty\right[};\\
0,&\text{if}\;\;\xi=0;\\
+\infty,&\text{otherwise}.
\end{cases}
\end{equation}
Then $\eta_i=e^{(\xi_i+\gamma(\omega-1))/(\gamma+1)}$.
\item 
\label{IVex:1iii}
Let $p\in\left[1,+\infty\right[$ 
and suppose that either $\phi=|\cdot|^p/p$ or
\begin{equation}
\phi\colon\xi\mapsto
\begin{cases}
\xi^p/p,&\text{if}\;\;\xi\in\ensuremath{\left[0,+\infty\right[};\\
+\infty,&\text{otherwise}.
\end{cases}
\end{equation}
Then 
\begin{equation}
\eta_i=
\begin{cases}
\left(\dfrac{W(\gamma(p-1)e^{(p-1)\xi_i})}{\gamma(p-1)}
\right)^{\frac{1}{p-1}},&\text{if}\;\;p>1;\\[4mm]
e^{\xi_i-\gamma},&\text{if}\;\;p=1.
\end{cases}
\end{equation}
\item
\label{IVex:1v}
Let $p\in\left[1,+\infty\right[$ and suppose that
\begin{equation}
\phi\colon\xi\mapsto
\begin{cases}
\xi^{-p}/p,&\text{if}\;\;\xi\in\ensuremath{\left]0,+\infty\right[};\\
+\infty,&\text{otherwise}.
\end{cases}
\end{equation}
Then 
\begin{equation}
\eta_i=\left(\frac{W(\gamma(p+1)e^{-(p+1)\xi_i})}{\gamma(p+1)}
\right)^{\frac{-1}{p+1}}.
\end{equation}
\item
\label{IVex:1vi}
Let $p\in\left]0,1\right[$ and suppose that
\begin{equation}
\phi\colon\xi\mapsto
\begin{cases}
-\xi^p/p,&\text{if}\;\;\xi\in\ensuremath{\left[0,+\infty\right[};\\
+\infty,&\text{otherwise}.
\end{cases}
\end{equation} 
Then 
\begin{equation}
\eta_i=\Bigg(\frac{W(\gamma(1-p)e^{(p-1)\xi_i})}{\gamma(1-p)}
\Bigg)^{\frac{1}{p-1}}.
\end{equation}
\end{enumerate}
\end{example}

\begin{example}
\label{IVex:2}
Let $\phi\in\Gamma_0(\ensuremath{\mathbb{R}})$ be such that 
$\ensuremath{\text{\rm dom}\,}\phi\cap\left]0,1\right[\neq\ensuremath{{\varnothing}}$ 
and let $\vartheta$ be the Fermi-Dirac entropy, i.e.,
\begin{equation}
\vartheta\colon\xi\mapsto
\begin{cases}
\xi\ln\xi+(1-\xi)\ln(1-\xi),&\text{if}\;\;\xi\in\left]0,1\right[;\\
0&\text{if}\;\;\xi\in\{0,1\};\\
\ensuremath{{+\infty}},&\text{otherwise}.
\end{cases}
\end{equation}
Set $\varphi\colon(\xi_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}
\mapsto\sum_{i=1}^m\phi(\xi_i)$ 
and $h\colon(\xi_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}
\mapsto\sum_{i=1}^m\vartheta(\xi_i)$. 
Note that $h$ is a Legendre function \cite[Sections~5 and 6]{BB97} 
and that $\ensuremath{\text{\rm int}\,}\ensuremath{\text{\rm dom}\,} h=\left]0,1\right[^m$ is bounded. Therefore,  
Proposition~\ref{IVpp:20a}\ref{IVcl:20b1} asserts that 
$\nabla h+\partial\varphi$ is coercive and that
$\ensuremath{\text{\rm dom}\,}(\nabla h+\partial\varphi)^{-1}=\ensuremath{\mathbb{R}}^m$. 
Now let $(\xi_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}\in\ensuremath{\mathbb{R}}^m$, 
set $(\eta_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}
=(\nabla h+\partial\varphi)^{-1}(\xi_i)_{1\ensuremath{\leqslant} i\ensuremath{\leqslant} m}$, 
and let $i\in\{1,\ldots,m\}$. Then $\eta_i$ can be computed 
as follows.
\begin{enumerate}
\item
\label{IVex:2i}
Let $\omega\in\ensuremath{\mathbb{R}}$ and suppose that
\begin{equation}
\phi\colon\xi\mapsto
\begin{cases}
\xi\ln\xi-\omega\xi,&\text{if}\;\;\xi\in\ensuremath{\left]0,+\infty\right[};\\
0,&\text{if}\;\;\xi=0;\\
\ensuremath{{+\infty}},&\text{otherwise}.
\end{cases}
\end{equation}
Then $\eta_i=-e^{\xi_i+\omega-1}/2+\sqrt{e^{2(\xi_i+\omega-1)}/4
+e^{\xi_i+\omega-1}}$.
\item
\label{IVex:2ii}
Suppose that
\begin{equation}
\phi\colon\xi\mapsto
\begin{cases}
(1-\xi)\ln(1-\xi)+\xi,&\text{if}\;\;\xi\in\left]-\infty,1\right[;\\
1,&\text{if}\;\;\xi=1;\\
\ensuremath{{+\infty}},&\text{otherwise}.
\end{cases}
\end{equation}
Then $\eta_i=1+e^{-\xi_i}/2-\sqrt{e^{-\xi_i}+e^{-2\xi_i}/4}$.
\end{enumerate}
\end{example}

